sys_script_include.script:
var filterModelForAsset = Class.create();
filterModelForAsset.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	filter: function(manufacturer) {
		//gs.info('Filter erstellt für model_category: ' + manufacturer);
		//gs.addInfoMessage("Zeile5");
        if (!manufacturer) {
			//gs.log('keine Model Category gefunden');
            return ''; // Wenn kein Wert vorhanden ist, wird ein leerer Filter zurückgegeben
        }

        var gr = new GlideRecord('cmdb_model');
        gr.addQuery('manufacturer', manufacturer); // Filtere nach der übergebenen Kategorie
        gr.query();

        var sysIdList = [];
        while (gr.next()) {
            sysIdList.push(gr.getValue('sys_id'));
        }

        // Rückgabe des Filters im passenden Format ("sys_idIN...")
        return sysIdList.join(',');
    },
    type: 'filterModelForAsset'
});
